import json, sys, collections

def has_imp(o):
    return 'impeccable' in json.dumps(o)

def clean(path):
    with open(path) as f:
        doc = json.load(f, object_pairs_hook=collections.OrderedDict)
    hooks = doc.get('hooks', {})
    removed = []
    for event in list(hooks):
        entries = hooks[event]
        if not isinstance(entries, list):
            continue
        kept = []
        for entry in entries:
            # nested shape: {"matcher":..., "hooks":[...]}
            if isinstance(entry, dict) and isinstance(entry.get('hooks'), list):
                inner = [h for h in entry['hooks'] if not has_imp(h)]
                if len(inner) != len(entry['hooks']):
                    removed.append(f"{event} (nested)")
                if not inner:
                    continue
                entry = collections.OrderedDict(entry)
                entry['hooks'] = inner
                kept.append(entry)
            elif has_imp(entry):
                removed.append(event)
            else:
                kept.append(entry)
        if kept:
            hooks[event] = kept
        else:
            del hooks[event]
            removed.append(f"{event} (event emptied, dropped)")
    with open(path, 'w') as f:
        json.dump(doc, f, indent=2)
        f.write('\n')
    print(f"{path}: removed -> {removed if removed else 'nothing'}")
    print(f"   impeccable refs remaining: {open(path).read().count('impeccable')}")

for p in sys.argv[1:]:
    clean(p)
